import { useState, useEffect } from 'react';
import { getCourseProgress, getAllUserProgress } from '../services/progressTracking';
import useStore from '../contexts/store';
import { getCurrentUser } from '../services/firebase';

/**
 * Hook to get and track user's progress for a specific course
 */
export function useCourseProgress(courseId: string) {
  const [progress, setProgress] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const { user } = useStore();
  
  useEffect(() => {
    const firebaseUser = getCurrentUser();
    const authedUid = firebaseUser?.uid;

    if (!user?.uid || !courseId || !authedUid || authedUid !== user.uid) {
      setProgress(null);
      setLoading(false);
      return;
    }
    
    const loadProgress = async () => {
      setLoading(true);
      const data = await getCourseProgress(user.uid, courseId);
      setProgress(data);
      setLoading(false);
    };
    
    loadProgress();
  }, [user?.uid, courseId]);
  
  return { progress, loading };
}

/**
 * Hook to get all user's progress across all courses
 */
export function useAllProgress() {
  const [progress, setProgress] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const { user } = useStore();
  
  useEffect(() => {
    const firebaseUser = getCurrentUser();
    const authedUid = firebaseUser?.uid;

    if (!user?.uid || !authedUid || authedUid !== user.uid) {
      setProgress([]);
      setLoading(false);
      return;
    }
    
    const loadProgress = async () => {
      setLoading(true);
      const data = await getAllUserProgress(user.uid);
      setProgress(data);
      setLoading(false);
    };
    
    loadProgress();
  }, [user?.uid]);
  
  return { progress, loading };
}

/**
 * Calculate course completion percentage
 */
export function calculateCompletionPercentage(progress: any, totalLessons: any) {
  if (!progress || !totalLessons) return 0;
  
  const completedCount = progress.completedLessons?.length || 0;
  return Math.round((completedCount / totalLessons) * 100);
}

/**
 * Check if a lesson is completed
 */
export function isLessonCompleted(progress: any, lessonId: any) {
  if (!progress) return false;
  return progress.completedLessons?.includes(lessonId) || false;
}

/**
 * Get quiz best score
 */
export function getQuizBestScore(progress: any, quizId: any) {
  if (!progress || !progress.quizAttempts?.[quizId]) return null;
  
  const attempts = progress.quizAttempts[quizId].attempts;
  if (!attempts || attempts.length === 0) return null;
  
  let bestScore = 0;
  let bestAttempt = null;
  
  attempts.forEach((attempt: any) => {
    const percentage = (attempt.score / attempt.totalQuestions) * 100;
    if (percentage > bestScore) {
      bestScore = percentage;
      bestAttempt = attempt;
    }
  });
  
  return bestAttempt;
}

/**
 * Get total quiz attempts
 */
export function getQuizAttemptCount(progress: any, quizId: any) {
  if (!progress || !progress.quizAttempts?.[quizId]) return 0;
  return progress.quizAttempts[quizId].attempts?.length || 0;
}
