import React, { useState } from 'react';
import {
  View, Text, TextInput, TouchableOpacity, ScrollView,
  KeyboardAvoidingView, Platform, Image, ActivityIndicator, useColorScheme,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import * as WebBrowser from 'expo-web-browser';
import * as Google from 'expo-auth-session/providers/google';
import * as AppleAuthentication from 'expo-apple-authentication';
import * as Crypto from 'expo-crypto';
import { Mail, Lock, User, Eye, EyeOff, Check, AlertCircle, Gift, ChevronDown, ChevronUp } from 'lucide-react-native';
import useStore from '../contexts/store';
import { useColors } from '../theme/theme';
import {
  loginWithEmailPassword,
  registerWithEmailPassword,
  loginWithGoogleCredential,
  loginWithAppleCredential,
  sendPasswordReset,
} from '../services/authService';
import { redeemReferral, type RedeemResult } from '../services/referralService';
import Confetti from '../components/ui/Confetti';
import PopIn from '../components/ui/PopIn';
import { useContentContainerStyle } from '../components/ui/ContentContainer';
import * as haptics from '../utils/haptics';

WebBrowser.maybeCompleteAuthSession();

export default function AuthScreen() {
  const { setUser, setActiveTab, activeTab, language } = useStore();
  const colors = useColors();
  const centerColumn = useContentContainerStyle('form');
  const isCreole = language === 'ht';
  const t = (fr: string, ht: string) => (isCreole ? ht : fr);

  // Themed aliases so the card/text/fields adapt to light + dark.
  const AZURE = colors.azure;
  const INK = colors.ink;
  const MUTED = colors.muted;
  const BORDER = colors.border;
  const FIELD = colors.surfaceAlt;

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPw, setShowPw] = useState(false);
  const [loading, setLoading] = useState(false);
  const [resetSent, setResetSent] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [focused, setFocused] = useState<'name' | 'email' | 'password' | 'referral' | null>(null);

  // Optional referral code entered at signup (collapsible / secondary).
  const [referralCode, setReferralCode] = useState('');
  const [showReferral, setShowReferral] = useState(false);
  // When a code was redeemed at signup we hold the result + the pending user and
  // show a brief overlay BEFORE flipping auth state (which unmounts this screen).
  const [celebration, setCelebration] = useState<{ result: RedeemResult; user: any } | null>(null);

  // Google OAuth client IDs from the edlight-academy Firebase project.
  // webClientId is the audience Firebase expects for the returned idToken.
  // androidClientId is the OAuth client registered against the Play App
  // Signing SHA-1 (Play-store installs are re-signed with that key). A second
  // Android client (...-8h16t4sk) exists for the upload-key cert if a
  // sideloaded/dev build ever needs it.
  const [, response, promptAsync] = Google.useAuthRequest({
    iosClientId: '618990331083-7snnbt287h2k9b82mkoufloj6um0epl4.apps.googleusercontent.com',
    androidClientId: '618990331083-mk0sbf8s32qtkm9bisvfht0pps351fh4.apps.googleusercontent.com',
    webClientId: '618990331083-lq461c7uqjr6sk389qi1tarcdrgfcobj.apps.googleusercontent.com',
  });

  React.useEffect(() => {
    if (response?.type === 'success') {
      const { authentication } = response;
      if (authentication?.idToken) {
        handleGoogleToken(authentication.idToken, authentication.accessToken ?? undefined);
      }
    }
  }, [response]);

  async function handleGoogleToken(idToken: string, accessToken?: string) {
    setError(null);
    setLoading(true);
    try {
      const user = await loginWithGoogleCredential(idToken, accessToken);
      setUser(user);
    } catch (e: any) {
      setError(e?.message || t('Connexion Google impossible.', 'Koneksyon Google echwe.'));
    } finally {
      setLoading(false);
    }
  }

  // Sign in with Apple — iOS only, and only when the device supports it.
  const colorScheme = useColorScheme();
  const [appleAvailable, setAppleAvailable] = useState(false);
  React.useEffect(() => {
    if (Platform.OS !== 'ios') return;
    AppleAuthentication.isAvailableAsync().then(setAppleAvailable).catch(() => setAppleAvailable(false));
  }, []);

  async function handleAppleSignIn() {
    setError(null);
    try {
      // Firebase verifies Apple's token against the SHA-256 of a nonce; we send
      // the hash to Apple and the raw value to Firebase.
      const rawNonce = Array.from(await Crypto.getRandomBytesAsync(16))
        .map((b) => b.toString(16).padStart(2, '0'))
        .join('');
      const hashedNonce = await Crypto.digestStringAsync(Crypto.CryptoDigestAlgorithm.SHA256, rawNonce);
      const credential = await AppleAuthentication.signInAsync({
        requestedScopes: [
          AppleAuthentication.AppleAuthenticationScope.FULL_NAME,
          AppleAuthentication.AppleAuthenticationScope.EMAIL,
        ],
        nonce: hashedNonce,
      });
      if (!credential.identityToken) {
        setError(t('Connexion Apple impossible.', 'Koneksyon Apple echwe.'));
        return;
      }
      const fullName = [credential.fullName?.givenName, credential.fullName?.familyName]
        .filter(Boolean)
        .join(' ');
      setLoading(true);
      const user = await loginWithAppleCredential(credential.identityToken, rawNonce, fullName || undefined);
      setUser(user);
    } catch (e: any) {
      // The user cancelling the native sheet is not an error.
      if (e?.code === 'ERR_REQUEST_CANCELED') return;
      setError(e?.message || t('Connexion Apple impossible.', 'Koneksyon Apple echwe.'));
    } finally {
      setLoading(false);
    }
  }

  async function handleSubmit() {
    if (!email.trim() || !password.trim() || (!isSignIn && !name.trim())) {
      setError(t('Remplis tous les champs.', 'Ranpli tout kaz yo.'));
      return;
    }
    setError(null);
    setLoading(true);
    try {
      if (activeTab === 'signin') {
        const user = await loginWithEmailPassword(email.trim(), password);
        setUser(user);
      } else {
        const user = await registerWithEmailPassword(email.trim(), password, name.trim());
        await finishSignup(user);
      }
    } catch (e: any) {
      setError(e?.message || t('Une erreur est survenue.', 'Yon erè rive.'));
    } finally {
      setLoading(false);
    }
  }

  /**
   * Complete a NEW-account signup. If the learner entered a friend's code, we
   * redeem it best-effort: on a real result (reward or a rejection reason) we
   * show a brief overlay, then flip auth state. A network/auth glitch never
   * blocks signup — we just proceed.
   */
  async function finishSignup(user: any) {
    const code = referralCode.trim();
    if (!code) {
      setUser(user);
      return;
    }
    const result = await redeemReferral(code);
    if (result.kind === 'ok') {
      haptics.success();
      setCelebration({ result, user });
    } else if (result.kind === 'rejected') {
      haptics.warn();
      setCelebration({ result, user });
    } else {
      // 'auth' | 'error' — best-effort, never block signup.
      setUser(user);
    }
  }

  // Auto-continue from the referral overlay into the app.
  React.useEffect(() => {
    if (!celebration) return;
    const ms = celebration.result.kind === 'ok' ? 2600 : 2200;
    const id = setTimeout(() => setUser(celebration.user), ms);
    return () => clearTimeout(id);
  }, [celebration, setUser]);

  /** Gentle localized note for a redeem rejection. */
  function reasonNote(reason: string): string {
    switch (reason) {
      case 'invalid_code':
        return t('Code invalide — mais ton compte est bien créé.', 'Kòd la pa bon — men kont ou kreye byen.');
      case 'already_referred':
        return t('Tu as déjà utilisé un code.', 'Ou deja sèvi ak yon kòd.');
      case 'self':
        return t('Tu ne peux pas utiliser ton propre code.', 'Ou pa ka sèvi ak pwòp kòd ou.');
      case 'too_old':
        return t('Ce code ne peut plus être utilisé sur ce compte.', 'Kòd sa a pa ka itilize sou kont sa a ankò.');
      default:
        return t('Code non appliqué — mais ton compte est prêt.', 'Kòd la pa aplike — men kont ou pare.');
    }
  }

  async function handleReset() {
    if (!email.trim()) {
      setError(t('Entre ton email pour réinitialiser ton mot de passe.', 'Antre imèl ou pou reyinisyalize modpas la.'));
      return;
    }
    setError(null);
    setLoading(true);
    try {
      await sendPasswordReset(email.trim());
      setResetSent(true);
    } catch (e: any) {
      setError(e?.message || t('Une erreur est survenue.', 'Yon erè rive.'));
    } finally {
      setLoading(false);
    }
  }

  function switchTab(tab: 'signin' | 'signup') {
    setActiveTab(tab);
    setError(null);
    setResetSent(false);
  }

  const isSignIn = activeTab === 'signin';

  // Reusable field wrapper: lifts to the surface + azure ring while focused.
  const fieldStyle = (key: 'name' | 'email' | 'password' | 'referral') => ({
    flexDirection: 'row' as const,
    alignItems: 'center' as const,
    borderRadius: 14,
    paddingHorizontal: 14,
    borderWidth: 1.5,
    backgroundColor: focused === key ? colors.surface : FIELD,
    borderColor: focused === key ? AZURE : BORDER,
  });

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: colors.bg }}>
      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
      >
        <ScrollView
          style={{ flex: 1 }}
          contentContainerStyle={[{ flexGrow: 1, justifyContent: 'center', paddingVertical: 32 }, centerColumn]}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
        >
          {/* Header — the brand mark, lit. Two soft glows behind the logo make
              the "EdLight" bulb read as genuinely illuminated (the signature). */}
          <View style={{ alignItems: 'center', paddingHorizontal: 24, marginBottom: 22 }}>
            <View style={{ width: 132, height: 132, alignItems: 'center', justifyContent: 'center', marginBottom: 14 }}>
              {/* warm outer glow */}
              <View style={{ position: 'absolute', width: 132, height: 132, borderRadius: 66, backgroundColor: '#FDB022', opacity: 0.14 }} />
              {/* azure inner glow */}
              <View style={{ position: 'absolute', width: 96, height: 96, borderRadius: 48, backgroundColor: AZURE, opacity: 0.10 }} />
              {/* logo tile */}
              <View
                style={{
                  width: 84,
                  height: 84,
                  borderRadius: 22,
                  backgroundColor: colors.surface,
                  alignItems: 'center',
                  justifyContent: 'center',
                  shadowColor: AZURE,
                  shadowOffset: { width: 0, height: 6 },
                  shadowOpacity: 0.16,
                  shadowRadius: 16,
                  elevation: 6,
                }}
              >
                <Image
                  source={require('../../assets/logo.png')}
                  style={{ width: 60, height: 60 }}
                  resizeMode="contain"
                />
              </View>
            </View>

            <Text style={{ fontSize: 12, fontWeight: '700', color: AZURE, letterSpacing: 1.5, textTransform: 'uppercase', marginBottom: 6 }}>
              EdLight Academy
            </Text>
            <Text style={{ fontSize: 25, fontWeight: '800', color: INK, letterSpacing: -0.4, textAlign: 'center' }}>
              {isSignIn ? t('Bon retour \u{1F44B}', 'Byenveni tounen \u{1F44B}') : t('Crée ton compte', 'Kreye kont ou')}
            </Text>
            <Text style={{ fontSize: 14.5, color: MUTED, marginTop: 5, textAlign: 'center', lineHeight: 20 }}>
              {isSignIn
                ? t('Continue ta préparation au Bac.', 'Kontinye preparasyon Bak ou.')
                : t('Gratuit — et ta progression reste sauvegardée.', 'Gratis — epi pwogrè ou ap konsève.')}
            </Text>
          </View>

          {/* Card */}
          <View
            style={{
              marginHorizontal: 20,
              backgroundColor: colors.surface,
              borderRadius: 24,
              borderWidth: 1,
              borderColor: BORDER,
              padding: 18,
              gap: 12,
              shadowColor: AZURE,
              shadowOffset: { width: 0, height: 8 },
              shadowOpacity: 0.06,
              shadowRadius: 20,
              elevation: 3,
            }}
          >
            {/* Segmented tabs */}
            <View style={{ flexDirection: 'row', backgroundColor: colors.surfaceAlt, borderRadius: 14, padding: 4, marginBottom: 2 }}>
              {(['signin', 'signup'] as const).map((tab) => {
                const active = activeTab === tab;
                return (
                  <TouchableOpacity
                    key={tab}
                    onPress={() => switchTab(tab)}
                    activeOpacity={0.9}
                    style={{
                      flex: 1,
                      paddingVertical: 10,
                      borderRadius: 10,
                      alignItems: 'center',
                      backgroundColor: active ? colors.surface : 'transparent',
                      shadowColor: active ? AZURE : 'transparent',
                      shadowOffset: { width: 0, height: 1 },
                      shadowOpacity: active ? 0.1 : 0,
                      shadowRadius: 3,
                      elevation: active ? 2 : 0,
                    }}
                  >
                    <Text style={{ fontWeight: '700', fontSize: 14, color: active ? AZURE : MUTED }}>
                      {tab === 'signin' ? t('Connexion', 'Koneksyon') : t('Inscription', 'Enskripsyon')}
                    </Text>
                  </TouchableOpacity>
                );
              })}
            </View>

            {!isSignIn && (
              <View style={fieldStyle('name')}>
                <User color={focused === 'name' ? AZURE : colors.faint} size={18} />
                <TextInput
                  style={{ flex: 1, paddingVertical: 14, marginLeft: 10, color: INK, fontSize: 16 }}
                  placeholder={t('Nom complet', 'Non konplè')}
                  value={name}
                  onChangeText={(v) => { setName(v); setError(null); }}
                  onFocus={() => setFocused('name')}
                  onBlur={() => setFocused(null)}
                  autoCapitalize="words"
                  textContentType="name"
                  placeholderTextColor={colors.faint}
                />
              </View>
            )}

            <View style={fieldStyle('email')}>
              <Mail color={focused === 'email' ? AZURE : colors.faint} size={18} />
              <TextInput
                style={{ flex: 1, paddingVertical: 14, marginLeft: 10, color: INK, fontSize: 16 }}
                placeholder={t('Adresse email', 'Adrès imèl')}
                value={email}
                onChangeText={(v) => { setEmail(v); setError(null); }}
                onFocus={() => setFocused('email')}
                onBlur={() => setFocused(null)}
                keyboardType="email-address"
                autoCapitalize="none"
                autoComplete="email"
                textContentType="emailAddress"
                placeholderTextColor={colors.faint}
              />
            </View>

            <View style={fieldStyle('password')}>
              <Lock color={focused === 'password' ? AZURE : colors.faint} size={18} />
              <TextInput
                style={{ flex: 1, paddingVertical: 14, marginLeft: 10, color: INK, fontSize: 16 }}
                placeholder={t('Mot de passe', 'Modpas')}
                value={password}
                onChangeText={(v) => { setPassword(v); setError(null); }}
                onFocus={() => setFocused('password')}
                onBlur={() => setFocused(null)}
                secureTextEntry={!showPw}
                autoCapitalize="none"
                textContentType={isSignIn ? 'password' : 'newPassword'}
                returnKeyType="go"
                onSubmitEditing={handleSubmit}
                placeholderTextColor={colors.faint}
              />
              <TouchableOpacity onPress={() => setShowPw((v) => !v)} hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }}>
                {showPw ? <EyeOff color={colors.faint} size={18} /> : <Eye color={colors.faint} size={18} />}
              </TouchableOpacity>
            </View>

            {/* Optional referral code — secondary, collapsible, signup only. */}
            {!isSignIn && (
              <View>
                <TouchableOpacity
                  onPress={() => setShowReferral((v) => !v)}
                  activeOpacity={0.7}
                  style={{ flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 4 }}
                  accessibilityRole="button"
                >
                  <Gift color={colors.azure} size={16} />
                  <Text style={{ flex: 1, color: MUTED, fontSize: 13, fontWeight: '600' }}>
                    {t('Un ami vous a invité ? Entrez son code', 'Yon zanmi envite w ? Antre kòd li')}
                  </Text>
                  {showReferral ? <ChevronUp color={colors.faint} size={16} /> : <ChevronDown color={colors.faint} size={16} />}
                </TouchableOpacity>
                {showReferral && (
                  <View style={[fieldStyle('referral'), { marginTop: 8 }]}>
                    <Gift color={focused === 'referral' ? AZURE : colors.faint} size={18} />
                    <TextInput
                      style={{ flex: 1, paddingVertical: 14, marginLeft: 10, color: INK, fontSize: 16, letterSpacing: 2 }}
                      placeholder={t('Code d’invitation', 'Kòd envitasyon')}
                      value={referralCode}
                      onChangeText={(v) => setReferralCode(v.toUpperCase())}
                      onFocus={() => setFocused('referral')}
                      onBlur={() => setFocused(null)}
                      autoCapitalize="characters"
                      autoCorrect={false}
                      maxLength={12}
                      placeholderTextColor={colors.faint}
                    />
                  </View>
                )}
              </View>
            )}

            {isSignIn && (
              <TouchableOpacity onPress={handleReset} style={{ alignSelf: 'flex-end' }} hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}>
                {resetSent ? (
                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
                    <Check color={AZURE} size={14} />
                    <Text style={{ color: AZURE, fontSize: 13, fontWeight: '600' }}>{t('Email envoyé', 'Imèl voye')}</Text>
                  </View>
                ) : (
                  <Text style={{ color: AZURE, fontSize: 13, fontWeight: '600' }}>{t('Mot de passe oublié ?', 'Ou bliye modpas ou ?')}</Text>
                )}
              </TouchableOpacity>
            )}

            {/* Inline error — non-blocking, tells you what to fix */}
            {error && (
              <View style={{ flexDirection: 'row', alignItems: 'flex-start', gap: 8, backgroundColor: colors.dangerSoft, borderWidth: 1, borderColor: colors.danger, borderRadius: 12, padding: 11 }}>
                <AlertCircle color={colors.danger} size={16} style={{ marginTop: 1 }} />
                <Text style={{ flex: 1, color: colors.danger, fontSize: 13, lineHeight: 18 }}>{error}</Text>
              </View>
            )}

            {/* Primary CTA */}
            <TouchableOpacity
              onPress={handleSubmit}
              disabled={loading}
              activeOpacity={0.9}
              style={{
                backgroundColor: AZURE,
                borderRadius: 16,
                paddingVertical: 16,
                alignItems: 'center',
                justifyContent: 'center',
                flexDirection: 'row',
                gap: 8,
                marginTop: 2,
                opacity: loading ? 0.7 : 1,
                shadowColor: AZURE,
                shadowOffset: { width: 0, height: 4 },
                shadowOpacity: 0.28,
                shadowRadius: 10,
                elevation: 4,
              }}
            >
              {loading && <ActivityIndicator color="#ffffff" size="small" />}
              <Text style={{ color: '#ffffff', fontWeight: '700', fontSize: 16 }}>
                {loading
                  ? t('Un instant…', 'Yon ti moman…')
                  : isSignIn
                  ? t('Se connecter', 'Konekte')
                  : t('Créer mon compte', 'Kreye kont mwen')}
              </Text>
            </TouchableOpacity>

            {/* Divider */}
            <View style={{ flexDirection: 'row', alignItems: 'center', marginVertical: 2 }}>
              <View style={{ flex: 1, height: 1, backgroundColor: colors.hairline }} />
              <Text style={{ color: colors.faint, fontSize: 12, marginHorizontal: 12 }}>{t('ou', 'oswa')}</Text>
              <View style={{ flex: 1, height: 1, backgroundColor: colors.hairline }} />
            </View>

            {/* Google */}
            <TouchableOpacity
              onPress={() => promptAsync()}
              disabled={loading}
              activeOpacity={0.85}
              style={{
                borderRadius: 16,
                paddingVertical: 14,
                alignItems: 'center',
                justifyContent: 'center',
                flexDirection: 'row',
                gap: 10,
                borderWidth: 1.5,
                borderColor: BORDER,
                backgroundColor: colors.surface,
              }}
            >
              <View style={{ width: 22, height: 22, borderRadius: 11, backgroundColor: colors.surface, borderWidth: 1, borderColor: BORDER, alignItems: 'center', justifyContent: 'center' }}>
                <Text style={{ color: '#4285F4', fontWeight: '800', fontSize: 14 }}>G</Text>
              </View>
              <Text style={{ color: INK, fontWeight: '600', fontSize: 15 }}>
                {t('Continuer avec Google', 'Kontinye ak Google')}
              </Text>
            </TouchableOpacity>

            {/* Sign in with Apple — required by App Store guideline 4.8 alongside
                Google. iOS only, using Apple's own button per their HIG. */}
            {appleAvailable && (
              <AppleAuthentication.AppleAuthenticationButton
                buttonType={AppleAuthentication.AppleAuthenticationButtonType.CONTINUE}
                buttonStyle={
                  colorScheme === 'dark'
                    ? AppleAuthentication.AppleAuthenticationButtonStyle.WHITE
                    : AppleAuthentication.AppleAuthenticationButtonStyle.BLACK
                }
                cornerRadius={16}
                style={{ height: 50, width: '100%' }}
                onPress={handleAppleSignIn}
              />
            )}
          </View>

          {/* Reassurance footer */}
          <Text style={{ textAlign: 'center', color: colors.faint, fontSize: 12, marginTop: 18, paddingHorizontal: 32, lineHeight: 17 }}>
            {isSignIn
              ? t('Ravi de te revoir sur EdLight.', 'Kontan wè ou ankò sou EdLight.')
              : t('En continuant, tu rejoins des milliers d’élèves qui révisent sur EdLight.', 'Lè ou kontinye, ou jwenn dè milye elèv k’ap revize sou EdLight.')}
          </Text>
        </ScrollView>
      </KeyboardAvoidingView>

      {/* Referral result overlay — shown briefly before entering the app. */}
      {celebration && (
        <TouchableOpacity
          activeOpacity={1}
          onPress={() => setUser(celebration.user)}
          style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(6,12,24,0.78)', alignItems: 'center', justifyContent: 'center', paddingHorizontal: 32 }}
        >
          {celebration.result.kind === 'ok' && <Confetti fireKey={String(celebration.result.reward.xp)} />}
          <PopIn>
            <View style={{ alignItems: 'center', gap: 10 }}>
              <Text style={{ fontSize: 44 }}>{celebration.result.kind === 'ok' ? '🎉' : '👍'}</Text>
              {celebration.result.kind === 'ok' ? (
                <>
                  <Text style={{ color: '#fff', fontSize: 20, fontWeight: '800', textAlign: 'center' }}>
                    {t('Bonus débloqué !', 'Bonus debloke !')}
                  </Text>
                  <Text style={{ color: '#fff', fontSize: 15, fontWeight: '600', textAlign: 'center', opacity: 0.95 }}>
                    {t(
                      `+${celebration.result.reward.streakFreeze} gel de série, +${celebration.result.reward.xp} XP`,
                      `+${celebration.result.reward.streakFreeze} jèl seri, +${celebration.result.reward.xp} XP`,
                    )}
                  </Text>
                </>
              ) : celebration.result.kind === 'rejected' ? (
                <Text style={{ color: '#fff', fontSize: 16, fontWeight: '600', textAlign: 'center', lineHeight: 22 }}>
                  {reasonNote(celebration.result.reason)}
                </Text>
              ) : null}
              <Text style={{ color: '#fff', fontSize: 13, opacity: 0.7, marginTop: 6 }}>
                {t('Appuyez pour continuer', 'Peze pou kontinye')}
              </Text>
            </View>
          </PopIn>
        </TouchableOpacity>
      )}
    </SafeAreaView>
  );
}
